SELECT p.gender, CAST(a.admittime AS DATE) AS admission_date, i.name AS icu_name, COUNT(*) AS num_stays, AVG(CASE WHEN l.valueuom = 'non-invasive diagnostic' THEN 1 ELSE 0 END) AS avg_non_invasive_diagnostics, MIN(CASE WHEN l.valueuom = 'non-invasive diagnostic' THEN 1 ELSE 0 END) AS min_non_invasive_diagnostics, MAX(CASE WHEN l.valueuom = 'non-invasive diagnostic' THEN 1 ELSE 0 END) AS max_non_invasive_diagnostics FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 38 AND 48 AND l.valueuom = 'non-invasive diagnostic' AND (l.charttime - a.admittime) BETWEEN 1 AND 7 AND (l.charttime - a.admittime) BETWEEN 5 AND 7 AND i.first_careunit = i.last_careunit GROUP BY p.gender, admission_date, icu_name;